dts.append("declare global { interface Window { GavIL: { %s; formatTime(seconds: number, hours?: boolean): string; haptic: typeof haptic; swap: typeof swap; motionOK: typeof motionOK; tokenMs: typeof tokenMs; keepFocus: typeof keepFocus; tapShield: typeof tapShield; parseTableCode: typeof parseTableCode; placardUrl: typeof placardUrl; art: typeof art; prefetchArt: typeof prefetchArt; recallOf: typeof recallOf; QR: typeof QR; talk: typeof talk; checkHint: typeof checkHint; mockServer: typeof mockServer; highlightLabel: typeof highlightLabel } } }" % "; ".join("%s: typeof %s"%(n,n) for n in names))
